var o=[{title:`Připravte každé stanoviště`,text:`Než lavici, stojan, stroj nebo nástavec zatížíte, zkontrolujte ho. Správně nastavte sedáky a bezpečnostní zarážky, používejte zámky tam, kde jsou potřeba, a ujistěte se, že jsou kotouče zajištěny z obou stran. Tašky a volné doplňky nechte mimo průchody. Pokud nevíte, jak stroj funguje, požádejte personál, aby vám ho ukázal.`},{title:`Sdílejte prostor`,text:`Vracejte jednoručky a kotouče na místo, otírejte vybavení, jak posilovna žádá, a vracejte nástavce kladek. Ve špičce nedržte několik strojů najednou. Slušně se zeptejte, zda se můžete zapojit, a než stanoviště budete sdílet, dohodněte se, jak bezpečně měnit váhu nebo sedák.`},{title:`Pomocníci a zarážky`,text:`U náročných bench pressů nebo dřepů nastavte bezpečnostní ramena, kdykoli to jde, a když pomocníka potřebujete, použijte takového, který ví, co dělá. Nespoléhejte na to, že si cizí člověk poblíž všimne neúspěšného opakování. Nastavení stojanu si procvičte s lehkou zátěží, než začnete zvedat těžké váhy, a nikdy nevstupujte do cizí dráhy zvedání.`},{title:`Rušná období`,text:`Mějte záložní plán pro oblíbené vybavení: přítah s jednoručkou může nahradit přítah na kladce a goblet dřep může nahradit dřep ve stojanu, pokud vám zátěž stále vyhovuje. Váš trénink nezávisí na tom, že získáte jedno konkrétní stanoviště. Spěch nebo plno kolem stále není důvod ustupovat z techniky ani vynechat zahřátí.`}];var n=[{label:`Mayo Clinic: bezpečnost a technika posilování`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`Knihovna cviků ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Stanovisko ACSM z roku 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var a={sections:o,sources:n};export{a as default,o as sections,n as sources};